(function(root){
  const field=(name,value)=>`- **${name}:** ${String(value||'').replace(/\n/g,'\n  ')}\n`;
  function encode(r){return `# ${r.title}\n\n${r.summary}\n\n${field('Stage',r.kind)}\n## Files\n\n`+r.files.map(f=>`### ${f.path}\n\n`+field('Decision',f.decision)+field('Change',f.change)+field('Reason',f.reason)+field('Comment',f.comment)+(f.nodes?field('Nodes',f.nodes.join(', ')):'')+(f.after?field('After',f.after.join(', ')):'')).join('\n');}
  function fields(text){const out={};let key;for(const line of text.split('\n')){const m=line.match(/^- \*\*([^:]+):\*\* ?(.*)$/);if(m){key=m[1].toLowerCase();out[key]=m[2];}else if(key&&line.startsWith('  '))out[key]+='\n'+line.slice(2);else key=null;}return out;}
  function parse(text,kind){const head=text.split(/^## Files\s*$/m);if(head.length!==2)throw Error('Add a Files heading.');const meta=fields(head[0]);if(meta.stage!==kind)throw Error(`Expected stage ${kind}.`);const title=head[0].match(/^# (.+)$/m)?.[1];if(!title)throw Error('Add a document title.');const summary=head[0].split('\n').slice(1).filter(l=>!l.startsWith('- **Stage:')).join('\n').trim();const parts=head[1].split(/^### (.+)$/m),files=[],seen=new Set();for(let i=1;i<parts.length;i+=2){const path=parts[i].trim(),v=fields(parts[i+1]);if(!path||path.startsWith('/')||path.includes('\\')||path.split('/').includes('..'))throw Error('Use project-relative file paths.');if(seen.has(path))throw Error('Duplicate file: '+path);seen.add(path);if(!['rewrite','no-change','implement','skip'].includes(v.decision))throw Error('Invalid decision for '+path);if(v.change===undefined||v.reason===undefined)throw Error('Add Change and Reason for '+path);const f={path,decision:v.decision,change:v.change,reason:v.reason,comment:v.comment||''};for(const key of ['nodes','after'])if(v[key]!==undefined)f[key]=v[key].split(',').map(x=>x.trim()).filter(Boolean);files.push(f);}return {kind,title,summary,files};}
  const selected=r=>r.files.filter(f=>['rewrite','implement'].includes(f.decision));
  function validatePlans(r){const paths=new Set(selected(r).map(f=>f.path)),visiting=new Set(),done=new Set();function visit(f){if(visiting.has(f.path))throw Error('Plan dependencies contain a cycle.');if(done.has(f.path))return;visiting.add(f.path);for(const a of f.after||[]){if(!paths.has(a))throw Error(`${f.path.split('/').pop()} requires ${a.split('/').pop()}.`);visit(r.files.find(p=>p.path===a));}visiting.delete(f.path);done.add(f.path);}selected(r).forEach(visit);}
  const api={encode,parse,selected,validatePlans};root.WorkflowModel=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
